def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the path and the visited set
    path = []
    visited = set()

    def search(current):
        if current == goal:
            return True
        if current in visited:
            return False
        visited.add(current)
        path.append(current)
        for neighbor in graph.get(current, []):
            if search(neighbor):
                return True
        path.pop()
        return False

    if not search(start):
