def find_path(graph, start, goal):
    # Initialize data structures
    visited = set()  # Nodes already visited
    path = {start: [start]}  # Maps nodes to the path leading to them

    # If the start node is not in the graph, return None
    if start not in graph:
        return None

    # If the goal node is the start node, we have our path
    if start == goal:
        return [start]

    # Start the search
    while path:
        # Choose the node to visit next
        current_node = None
        for node in path:
            if current_node is None or len(path[node]) < len(path[current_node]):
                current_node = node

        # If we reach the goal, the path is found
        if current_node == goal:
            return path[current_node]

        # Mark the current node as visited
        visited.add(current_node)

        # Explore neighbors
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                # If the neighbor is the goal, we found the path
                if neighbor == goal:
                    path[neighbor] = path[current_node] + [neighbor]
                    return path[neighbor]

                # Add the neighbor to the path
                if neighbor not in path:
                    path[neighbor] = path[current_node] + [neighbor]

    # If we exhaust all nodes without finding the goal, return None
    return None
